query GET_EVENT_LISTINGS($filters: FilterInputDtoInput, $pageSize: Int) {
  eventListings(filters: $filters, pageSize: $pageSize) {
    data {
      event {
        id
        title
        date
        startTime
        endTime
        content
        contentUrl
        flyerFront
        isTicketed
        cost
        minimumAge
        attending
        interestedCount
        isFestival
        venue {
          name
          address
          contentUrl
          capacity
          area { name }
          location { latitude longitude }
        }
        artists {
          name
        }
        genres {
          name
        }
        promoters {
          name
        }
        pick {
          blurb
        }
        images {
          filename
        }
      }
    }
    totalResults
  }
}
